async function captureMove(page,targetId,screenName){
 const cdp=await page.context().newCDPSession(page);await cdp.send("Network.enable");
 const started=Date.now(),requests=new Map(),meta=new Map(),events=[],toasts=new Set(),bodyTasks=[];
 const headers=(all)=>Object.fromEntries(Object.entries(all||{}).filter(([k])=>["access-control-allow-origin","access-control-allow-credentials","content-type","server","cf-ray"].includes(k.toLowerCase())));
 cdp.on("Network.requestWillBeSent",e=>{try{if(!e.request.url.startsWith("https://api.bex.co/graphql")||e.request.method!=="POST")return;const raw=JSON.parse(e.request.postData||"null"),qs=Array.isArray(raw)?raw:[raw];if(!qs.some(x=>x?.variables?.id===targetId&&(["SetEnvironmentServices","SetEnvironmentEnvGroups"].includes(x.operationName)||/setEnvironment(?:Services|EnvGroups)\b/.test(x.query||""))))return;requests.set(e.requestId,{requestId:e.requestId,at:new Date().toISOString(),offsetMs:Date.now()-started,timestamp:e.timestamp,url:e.request.url,method:e.request.method,body:raw});}catch{}});
 cdp.on("Network.responseReceivedExtraInfo",e=>{meta.set(e.requestId,{status:e.statusCode,headers:headers(e.headers),offsetMs:Date.now()-started});});
 cdp.on("Network.responseReceived",e=>{if(requests.has(e.requestId))events.push({requestId:e.requestId,kind:"response",offsetMs:Date.now()-started,status:e.response.status,headers:headers(e.response.headers)});});
 cdp.on("Network.loadingFailed",e=>{if(requests.has(e.requestId))events.push({requestId:e.requestId,kind:"failed",offsetMs:Date.now()-started,errorText:e.errorText,blockedReason:e.blockedReason,corsErrorStatus:e.corsErrorStatus,canceled:e.canceled});});
 cdp.on("Network.loadingFinished",e=>{if(!requests.has(e.requestId))return;events.push({requestId:e.requestId,kind:"finished",offsetMs:Date.now()-started});bodyTasks.push(cdp.send("Network.getResponseBody",{requestId:e.requestId}).then(r=>{try{events.push({requestId:e.requestId,kind:"jsonBody",body:JSON.parse(r.body)});}catch{events.push({requestId:e.requestId,kind:"nonJsonBody",bodyBytes:r.body.length});}}).catch(()=>{}));});
 let screenTaken=false,error;
 try{
  await page.getByRole("button",{name:"Move",exact:true}).click();
  for(let i=0;i<48;i++){await page.waitForTimeout(1000);const now=await page.locator("[data-sonner-toast]").allTextContents();for(const t of now)toasts.add(t);if(!screenTaken&&now.some(t=>/fail|unknown|could|took|retry|cannot|error/i.test(t))){await page.screenshot({path:screenName,fullPage:false});screenTaken=true;}}
 }catch(e){error=String(e).split("\n")[0];}
 await Promise.race([Promise.allSettled(bodyTasks),page.waitForTimeout(2000)]);
 const result={at:new Date().toISOString(),durationMs:Date.now()-started,targetId,requests:[...requests.values()].map(r=>({...r,http:meta.get(r.requestId)})),events,toasts:[...toasts],screenTaken,error,ariaTail:(await page.getByRole("main").ariaSnapshot()).slice(-2800)};
 await cdp.detach();return result;
}

