mutation CreateProject($name: String!, $ownerId: String!) {
  createProject(name: $name, ownerId: $ownerId) {
    ...ProjectFields
    __typename
  }
}

fragment ProjectFields on Project {
  id
  name
  ownerId
  createdAt
  serviceIds
  databaseIds
  keyValueIds
  __typename
}

mutation CreateEnvGroup($name: String!, $ownerId: String, $envVars: [EnvGroupVarInput!], $secretFiles: [EnvGroupSecretFileInput!], $serviceIds: [String!], $environmentId: String) {
  createEnvGroup(
    name: $name
    ownerId: $ownerId
    envVars: $envVars
    secretFiles: $secretFiles
    serviceIds: $serviceIds
    environmentId: $environmentId
  ) {
    id
    name
    __typename
  }
}

mutation DeleteService($id: String!, $confirm: String) {
  deleteService(id: $id, confirm: $confirm)
}
